<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { accounts, activityIndex, historicalRecords, learnerName, spaceName, chapterOf, modelIndex, materialIndex, taskIndex } from './data';
import { state, sessionRecord } from './state';
const props=defineProps<{page:string}>();
const route=useRoute(),router=useRouter();
const q=(key:string,fallback='')=>String(route.query[key]||fallback);
const page=computed(()=>props.page||'work');
const nav=[['work','工作台','01'],['users','用户与学习','02'],['materials','教材与目标','03'],['models','模型','04'],['maintenance','维护与发布','05'],['operations','运行','06']];
const names:Record<string,string>={work:'工作台',users:'用户与学习',materials:'教材与目标',models:'模型',maintenance:'维护与发布',operations:'运行',account:'账号档案',case:'学习案例',object:'对象详情'};
const active=computed(()=>page.value==='case'?'users':page.value==='account'?'users':page.value==='object'?q('area','models'):page.value);
const reason=ref(''),note=ref(''),notice=ref('');
watch(()=>route.fullPath,()=>{reason.value='';note.value='';notice.value='';});
function go(to:string,query:Record<string,string>={}){void router.push({path:`/${to}`,query});}
function filter(key:string,value:string){void router.replace({query:{...route.query,[key]:value,p:'1'}});}
function back(){void router.push(q('from','/users'));}
type Row={id:string;title:string;type:string;status:string;extra:string};
const dataset=computed<Row[]>(()=>{
 if(page.value==='users')return accounts.map(a=>({id:a.id,title:a.name,type:a.role,status:'可用',extra:a.role==='学生'?'个人学习档案':'独立家长账号'}));
 if(page.value==='models')return modelIndex.map(o=>({id:o.id,title:o.title,type:o.space,status:o.status,extra:`${o.type} · ${o.version}`}));
 if(page.value==='materials')return materialIndex.map(o=>({id:o.id,title:o.title,type:'教材',status:o.status,extra:o.version}));
 if(page.value==='maintenance')return state.issues.map(o=>({id:o.id,title:o.reason,type:'结果复核',status:o.status,extra:`${learnerName(o.learner)} · ${spaceName(o.space)}`}));
 if(page.value==='operations')return taskIndex.map(o=>({id:o.id,title:o.title,type:o.title,status:o.status,extra:o.date}));
 return [];
});
const types=computed(()=>[...new Set(dataset.value.map(r=>r.type))]);
const statuses=computed(()=>[...new Set(dataset.value.map(r=>r.status))]);
const filtered=computed(()=>dataset.value.filter(r=>(!q('search')||`${r.id} ${r.title} ${r.extra}`.toLowerCase().includes(q('search').toLowerCase()))&&(!q('type')||r.type===q('type'))&&(!q('status')||r.status===q('status'))).sort((a,b)=>q('sort')==='desc'?b.id.localeCompare(a.id):a.id.localeCompare(b.id)));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/20)));
const p=computed(()=>Math.max(1,Math.min(Number(q('p','1'))||1,pages.value)));
const rows=computed(()=>filtered.value.slice((p.value-1)*20,p.value*20));
const account=computed(()=>accounts.find(a=>a.id===q('id')));
const accountActivities=computed(()=>activityIndex.filter(a=>a.learner===account.value?.id));
const accountLive=computed(()=>state.sessions.filter(a=>a.learner===account.value?.id));
const issue=computed(()=>state.issues.find(i=>i.id===q('issue')&&i.recordId===q('id')));
const session=computed(()=>state.sessions.find(s=>s.id===q('id')));
const indexed=computed(()=>activityIndex.find(a=>a.id===q('id')));
const record=computed(()=>{
 if(session.value)return sessionRecord(session.value);
 if(issue.value)return historicalRecords(issue.value.learner,issue.value.space).find(r=>r.id===issue.value!.recordId);
 return undefined;
});
const identity=computed(()=>record.value?{learner:record.value.learner,space:record.value.space,chapter:record.value.chapter}:indexed.value);
const granted=computed(()=>!!identity.value&&!!state.access[q('id')]);
const tab=computed(()=>q('tab','overview'));
const selectedModel=computed(()=>modelIndex.find(m=>m.id===q('id')));
const selectedMaterial=computed(()=>materialIndex.find(m=>m.id===q('id')));
const selectedTask=computed(()=>taskIndex.find(m=>m.id===q('id')));
const object=computed(()=>selectedModel.value||selectedMaterial.value||selectedTask.value);
function choose(row:Row){if(page.value==='users')go('account',{id:row.id,from:route.fullPath});else if(page.value==='maintenance'){const i=state.issues.find(x=>x.id===row.id)!;go('case',{id:i.recordId,issue:i.id,from:route.fullPath});}else go('object',{id:row.id,area:page.value,from:route.fullPath});}
function grant(){if(!reason.value.trim()||!identity.value)return;state.access[q('id')]=reason.value.trim();}
function save(){if(!issue.value||!note.value.trim())return;issue.value.note=note.value.trim();issue.value.status='已记录意见';notice.value='已保存人工意见。没有修改模型、学习事实或掌握判断，复核事项仍可追踪。';}
const pending=computed(()=>state.issues.filter(i=>i.status==='待复核'));
</script>
<template><div class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="structure.html?role=admin">DeerMind<span>管理后台</span></a><nav aria-label="管理导航"><button v-for="[id,label,n] in nav" :key="id" :class="{active:active===id}" @click="go(id!)"><small>{{ n }}</small>{{ label }}</button></nav><div class="sidebar-footer"><span class="avatar">管</span><div>管理员<small>独立管理身份 · 本地走查</small></div></div></aside><div class="admin-body"><header class="admin-top"><span>管理后台 <span class="muted"> / </span> {{ names[page]||'详情' }}</span><span class="muted small">按事项查看，按版本追溯</span></header><main class="admin-main"><p v-if="notice" class="notice" role="status">{{ notice }}</p>
 <template v-if="page==='work'"><div class="page-heading"><div><p class="eyebrow">今天的工作</p><h1>从需要处理的事项开始</h1><p class="muted">摘要指向原事项。处理之后，仍可从历史中查到依据。</p></div></div><div class="work-metrics"><button @click="go('maintenance',{status:'待复核'})"><strong>{{ pending.length }}</strong><span>待复核事项</span><small>本轮实际提交</small></button><button @click="go('operations',{status:'待核对'})"><strong>{{ taskIndex.filter(t=>t.status==='待核对').length }}</strong><span>待核对任务</span><small>合成任务集合</small></button><button @click="go('models',{status:'候选'})"><strong>{{ modelIndex.filter(m=>m.status==='候选').length }}</strong><span>候选版本条目</span><small>目录走查资料</small></button></div><section class="panel"><div class="section-title"><h2>结果复核</h2><button class="text" @click="go('maintenance')">查看全部 →</button></div><div v-if="!pending.length" class="empty compact"><h3>没有待复核事项</h3><p>家长在具体学习记录上提交后，会出现在这里。也可以从用户目录开始普通抽查。</p><button @click="go('users',{type:'学生'})">查找学生</button></div><button v-for="i in pending.slice(0,6)" :key="i.id" class="record-row" @click="go('case',{id:i.recordId,issue:i.id,from:route.fullPath})"><span><strong>{{ i.reason }}</strong><small>{{ learnerName(i.learner) }} · {{ spaceName(i.space) }} · {{ i.id }}</small></span><span>查看事项 →</span></button></section><div class="admin-links"><button @click="go('materials')">准备与核对教材 →</button><button @click="go('users')">账号与学习档案 →</button><button @click="go('models')">查看模型定义 →</button></div></template>
 <template v-else-if="['users','models','materials','maintenance','operations'].includes(page)"><div class="page-heading"><div><p class="eyebrow">对象目录</p><h1>{{ names[page] }}</h1><p class="muted">{{ page==='users'?'先定位账号，再进入对应档案与获准学习记录。':page==='models'?'按 Space、对象和版本查找；个人证据由具体案例进入。':page==='operations'?'任务处理与服务配置分开。先核对原结果，再决定后续动作。':page==='maintenance'?'每项复核保留自己的对象、说明和处理记录。':'教材是内容入口，章节、映射与目标准备在详情中组织。' }}</p></div><span class="count-badge">{{ dataset.length.toLocaleString() }} 条</span></div><p v-if="page!=='maintenance'" class="data-note">合成索引用于检索与分页走查；这些条目不代表已发布内容、真实用户或真实运行结果。</p><div class="filters"><label class="search-field">查找对象<input :value="q('search')" @input="filter('search',($event.target as HTMLInputElement).value)" :placeholder="page==='users'?'姓名或账号标识':'名称或对象标识'" aria-label="查找对象"/></label><label>类别<select :value="q('type')" @change="filter('type',($event.target as HTMLSelectElement).value)"><option value="">全部类别</option><option v-for="v in types" :key="v">{{ v }}</option></select></label><label>状态<select :value="q('status')" @change="filter('status',($event.target as HTMLSelectElement).value)"><option value="">全部状态</option><option v-for="v in statuses" :key="v">{{ v }}</option></select></label><label>排序<select :value="q('sort','asc')" @change="filter('sort',($event.target as HTMLSelectElement).value)"><option value="asc">编号升序</option><option value="desc">编号降序</option></select></label></div><div class="section-title"><span class="muted small">当前条件：{{ filtered.length.toLocaleString() }} 条 · 每页 20 条</span><button class="text" @click="router.replace({path:route.path})">清除筛选</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>对象</th><th>类型</th><th>状态</th><th>相关信息</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{ r.title }}</strong><small>{{ r.id }}</small></td><td>{{ r.type }}</td><td><span class="tag">{{ r.status }}</span></td><td>{{ r.extra }}</td><td><button class="text" @click="choose(r)">查看详情 →</button></td></tr></tbody></table></div><div v-if="!rows.length" class="empty"><h2>当前筛选下没有对象</h2><p>可调整查询条件；没有数据与处理失败是不同状态。</p></div><div class="pagination"><span>第 {{ p }} / {{ pages }} 页</span><button :disabled="p===1" @click="router.replace({query:{...route.query,p:p-1}})">上一页</button><button :disabled="p===pages" @click="router.replace({query:{...route.query,p:p+1}})">下一页</button></div></template>
 <template v-else-if="page==='account'&&account"><button class="back" @click="back">← 返回目录，保留筛选</button><div class="page-heading"><div><p class="eyebrow">{{ account.id }} · {{ account.role }}</p><h1>{{ account.name }}</h1></div><span class="tag">账号元信息</span></div><section class="panel"><h2>账号档案</h2><p>独立{{ account.role }}身份；开户、找回和关系修改在各自操作中记录核实依据。</p><p class="muted">此轮只读身份索引；关系维护和恢复表单未展开。</p></section><section v-if="account.role==='学生'" class="section-space"><h2>学习活动目录</h2><p class="muted">选择活动后明确访问事项和用途，再查看原作答及模型依据。</p><button v-for="s in accountLive" :key="s.id" class="record-row" @click="go('case',{id:s.id,from:route.fullPath})"><span><strong>{{ chapterOf(s.chapter)?.name }} · 本轮实际活动</strong><small>{{ s.id }} · {{ spaceName(s.space) }}</small></span><span>进入案例 →</span></button><button v-for="a in accountActivities" :key="a.id" class="record-row" @click="go('case',{id:a.id,from:route.fullPath})"><span><strong>{{ a.title }}</strong><small>{{ a.id }} · {{ a.date }} · 合成索引</small></span><span>{{ a.status }} →</span></button></section></template>
 <template v-else-if="page==='case'&&identity"><button class="back" @click="back">← 返回来源位置</button><div class="page-heading"><div><p class="eyebrow">{{ q('id') }}{{ issue?' · '+issue.id:'' }}</p><h1>{{ learnerName(identity.learner) }} · {{ chapterOf(identity.chapter)?.name }}</h1><p class="muted">{{ identity.learner }} / {{ spaceName(identity.space) }} / {{ record?.date||indexed?.date }}</p></div><span class="tag">{{ issue?.status||'普通抽查' }}</span></div>
  <form v-if="!granted" class="panel access-panel" @submit.prevent="grant"><h2>明确本次查看用途</h2><p v-if="issue">来源事项：{{ issue.reason }}</p><p>仅进入这条活动或判断的相关资料。目录可查不等于全部学习内容可读。</p><label class="field">事项或抽查说明<textarea v-model="reason" rows="3" aria-label="查看用途" placeholder="例如：核对家长提交的这条结果复核事项"/></label><button class="primary" :disabled="!reason.trim()">记录用途，进入案例</button><p class="muted small">这是界面流程走查，不是服务端权限验证。</p></form>
  <template v-else><p class="access-bar">当前用途：{{ state.access[q('id')] }} <button class="text" @click="delete state.access[q('id')]">结束本次查看</button></p><nav class="detail-tabs" aria-label="案例详情"><button v-for="[id,label] in [['overview','概览'],['interaction','交互过程'],['evaluation','评价依据'],['versions','关联内容与版本'],['handling','处理记录']]" :key="id" :class="{active:tab===id}" @click="router.replace({query:{...route.query,tab:id}})">{{ label }}</button></nav>
   <section v-if="tab==='overview'" class="panel"><h2>本次发生了什么</h2><dl class="detail-grid"><dt>资料性质</dt><dd>{{ session?'本浏览器实际学习操作':'预写索引／参考资料' }}</dd><dt>当前结果</dt><dd>{{ record?.outcome||indexed?.status }}；未执行真实模型链</dd><dt>实际帮助</dt><dd>{{ record?.help||'此索引未附完整帮助记录，不能推定独立完成。' }}</dd><dt>复核说明</dt><dd>{{ issue?.reason||'没有关联反馈；以登记的抽查用途为准。' }}</dd></dl><div class="action-bar"><button @click="router.replace({query:{...route.query,tab:'interaction'}})">查看交互事实</button><button @click="router.replace({query:{...route.query,tab:'evaluation'}})">查看评价依据</button></div></section>
   <section v-else-if="tab==='interaction'" class="panel"><h2>交互过程</h2><p class="muted">先看实际输入与展示，再看系统解释；不同类型不会混成一段聊天摘要。</p><ol class="timeline"><li><strong>材料与原始输入</strong><p>{{ record?.problem||record?.title||'只有合成活动索引，未附原输入。' }}</p></li><li><strong>已展示的帮助</strong><p>{{ record?.help||'资料未提供，不填造展示记录。' }}</p></li><li><strong>学习者提交</strong><blockquote>{{ record?.answer||'未提供作答记录' }}</blockquote></li><li v-if="record?.practice"><strong>讲解中的练习 · 尚未判定</strong><p>{{ record.practice.problem }}</p><blockquote>{{ record.practice.answer }}</blockquote></li><li><strong>Observation、校验与 Policy</strong><p>未执行模型链；没有可供查看的正式解释或决策结果。</p></li></ol></section>
   <section v-else-if="tab==='evaluation'" class="panel"><h2>评价依据与有效性</h2><p class="notice">此活动没有运行真实 Evaluation。不会根据页面操作生成 Evidence 或 Belief。</p><dl class="detail-grid"><dt>表现记录</dt><dd>{{ record?.outcome||'索引未附表现' }}{{ record?.id.startsWith('R-')?'（预写参考状态）':'' }}</dd><dt>Evidence</dt><dd>未执行；不能用参考答案替代证据解释。</dd><dt>Belief 变化</dt><dd>未执行；没有可比较的新旧值。</dd><dt>章节概况</dt><dd>另一组明确标记的预写参考，不由本活动计算。</dd></dl><button @click="router.replace({query:{...route.query,tab:'interaction'}})">反查原输入与帮助</button></section>
   <section v-else-if="tab==='versions'" class="panel"><h2>本案例采用的内容</h2><dl class="detail-grid"><dt>学习空间</dt><dd>{{ identity.learner }} / {{ spaceName(identity.space) }}</dd><dt>章节</dt><dd>{{ chapterOf(identity.chapter)?.name }}</dd><dt>讲解内容</dt><dd>低保真合成资料 v1；不是正式教材发布版本。</dd><dt>正式模板、KC 与评价规则</dt><dd>尚未建立本活动的正式引用，不填入无关目录对象。</dd></dl><p class="muted">模型目录可独立检索定义样例；它的存在不代表本活动已经采用这些定义。</p><button @click="go('models')">浏览模型目录</button></section>
   <section v-else class="panel"><h2>人工处理记录</h2><template v-if="issue"><p>复核原文：{{ issue.reason }}</p><p v-if="issue.note">已记录意见：{{ issue.note }}</p><form @submit.prevent="save"><label class="field">本次意见<textarea v-model="note" rows="4" aria-label="人工处理意见" placeholder="写明已核对的依据、还不能判断的部分及下一步…"/></label><button class="primary" :disabled="!note.trim()">保存人工意见</button></form><p class="muted small">保存意见不表示已经修复；候选、检查、发布与影响处理后续继续设计。</p></template><p v-else class="muted">当前是普通抽查，没有关联维护事项；本轮未展开从抽查创建候选的操作。</p></section>
  </template></template>
 <template v-else-if="page==='object'&&object"><button class="back" @click="back">← 返回目录，保留筛选</button><div class="page-heading"><div><p class="eyebrow">{{ object.id }}</p><h1>{{ object.title }}</h1><p class="muted">{{ object.status }} · 合成目录对象</p></div></div><section class="panel"><h2>对象与版本</h2><dl class="detail-grid"><dt>标识</dt><dd>{{ object.id }}</dd><dt>类型</dt><dd>{{ selectedModel?`${selectedModel.space} / ${selectedModel.type}`:selectedMaterial?'教材材料':'运行任务' }}</dd><dt>版本或时间</dt><dd>{{ selectedModel?.version||selectedMaterial?.version||selectedTask?.date }}</dd><dt>关联</dt><dd>此规模索引尚未附完整关联内容，不将无关案例作为引用。</dd></dl><p class="muted">本轮验证对象查找、详情和返回。完整编辑、版本对照及发布不在此画面中模拟成功。</p></section></template>
 <div v-else class="empty"><h1>没有找到这个对象</h1><p>请回到目录重新定位。</p><button @click="go('work')">返回工作台</button></div>
</main></div></div></template>
